+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8" />
+<title>Nebula — Barnes-Hut Galaxy Simulator</title>
+<meta name="viewport" content="width=device-width, initial-scale=1" />
+<style>
+  :root { color-scheme: dark; }
+  html, body { margin: 0; height: 100%; background: #05050a; overflow: hidden; font-family: 'Segoe UI', system-ui, sans-serif; }
+  canvas { display: block; position: fixed; inset: 0; cursor: crosshair; }
+  #ui {
+    position: fixed; top: 12px; left: 12px; z-index: 10;
+    background: rgba(10, 10, 20, 0.72); backdrop-filter: blur(6px);
+    border: 1px solid rgba(255,255,255,0.08); border-radius: 12px;
+    padding: 14px 16px; color: #dfe6ff; width: 260px; font-size: 13px;
+    box-shadow: 0 8px 30px rgba(0,0,0,0.5);
+  }
+  #ui h1 { font-size: 15px; margin: 0 0 8px; letter-spacing: 0.5px; color: #a9c2ff; }
+  #ui p.hint { opacity: 0.6; margin: 4px 0 10px; line-height: 1.4; }
+  #ui label { display: flex; justify-content: space-between; align-items: center; margin: 6px 0; gap: 8px; }
+  #ui input[type=range] { flex: 1; }
+  #ui .row { display: flex; gap: 6px; margin-top: 8px; flex-wrap: wrap; }
+  #ui button {
+    background: linear-gradient(180deg, #2a3a66, #1c2748); color: #dfe6ff; border: 1px solid #3a4d85;
+    border-radius: 7px; padding: 6px 9px; font-size: 12px; cursor: pointer; flex: 1;
+  }
+  #ui button:hover { background: linear-gradient(180deg, #34477d, #223058); }
+  #stats { position: fixed; top: 12px; right: 12px; z-index: 10; color: #8fa0d0; font-size: 12px;
+    background: rgba(10,10,20,0.6); border-radius: 10px; padding: 8px 12px; text-align: right; }
+  #stats b { color: #d7e2ff; }
+  #toggle { position: fixed; bottom: 12px; left: 12px; z-index: 10; color: #6f7fae; font-size: 11px; }
+</style>
+</head>
+<body>
+<canvas id="c"></canvas>
+<div id="ui">
+  <h1>✦ NEBULA — Barnes-Hut Gravity Sim</h1>
+  <p class="hint">Click / drag to fling a new mass into the sim. Scroll to zoom.</p>
+  <label>Bodies: <span id="nVal">400</span>
+    <input id="nRange" type="range" min="50" max="2000" step="50" value="400" />
+  </label>
+  <label>Speed: <span id="speedVal">1.0×</span>
+    <input id="speedRange" type="range" min="0" max="4" step="0.1" value="1" />
+  </label>
+  <label>θ (accuracy/perf): <span id="thetaVal">0.6</span>
+    <input id="thetaRange" type="range" min="0.1" max="1.5" step="0.05" value="0.6" />
+  </label>
+  <label><input id="trails" type="checkbox" checked style="flex:0" /> Trails</label>
+  <label><input id="showTree" type="checkbox" style="flex:0" /> Show Barnes-Hut tree</label>
+  <label><input id="mergeOn" type="checkbox" checked style="flex:0" /> Collisions merge (accretion)</label>
+  <div class="row">
+    <button id="btnGalaxy">Spiral Galaxy</button>
+    <button id="btnCluster">Random Cluster</button>
+  </div>
+  <div class="row">
+    <button id="btnBinary">Binary System</button>
+    <button id="btnReset">Reset</button>
+  </div>
+  <div class="row">
+    <button id="btnPause">Pause</button>
+  </div>
+</div>
+<div id="stats">
+  fps: <b id="fps">0</b><br/>
+  bodies: <b id="bcount">0</b><br/>
+  step: <b id="stepTime">0</b> ms
+</div>
+<div id="toggle">Nebula · N-body engine with Barnes-Hut quadtree · vanilla JS + Canvas2D</div>
+
+<!--
+  physics.inline.js is an auto-generated, dependency-free copy of physics.mjs
+  with the `export` keywords stripped, loaded as a classic (non-module)
+  script so this page runs by simply double-clicking it (file://) with no
+  local server and no ES-module / CORS restrictions. physics.mjs itself
+  (the ES module) is what the Node test suite (test.mjs) and any code
+  reuse should import from — keep the two in sync if you edit the engine.
+-->
+<script src="physics.inline.js"></script>
+<script>
+
+const canvas = document.getElementById('c');
+const ctx = canvas.getContext('2d');
+function resize() { canvas.width = innerWidth; canvas.height = innerHeight; }
+addEventListener('resize', resize); resize();
+
+let bodies = [];
+let camera = { x: 0, y: 0, zoom: 1.4 };
+let paused = false;
+let theta = 0.6;
+let speedMul = 1;
+let trailsOn = true;
+let showTree = false;
+let mergeOn = true;
+
+const nRange = document.getElementById('nRange');
+const nVal = document.getElementById('nVal');
+const speedRange = document.getElementById('speedRange');
+const speedVal = document.getElementById('speedVal');
+const thetaRange = document.getElementById('thetaRange');
+const thetaVal = document.getElementById('thetaVal');
+const trailsBox = document.getElementById('trails');
+
+function spawnGalaxy() {
+  bodies = makeGalaxy({ n: Number(nRange.value), seed: Date.now() & 0xffff, radius: 260, centralMass: 26000 });
+  camera.zoom = 1.4;
+}
+function spawnCluster() {
+  const rng = makeRng(Date.now() & 0xffff);
+  const n = Number(nRange.value);
+  bodies = [];
+  for (let i = 0; i < n; i++) {
+    const ang = rng() * Math.PI * 2;
+    const r = rng() * 300;
+    bodies.push({
+      pos: { x: Math.cos(ang) * r, y: Math.sin(ang) * r },
+      vel: { x: (rng() - 0.5) * 2, y: (rng() - 0.5) * 2 },
+      mass: 2 + rng() * 8,
+      radius: 2, color: `hsl(${(200 + rng() * 160).toFixed(0)},80%,68%)`,
+    });
+  }
+  camera.zoom = 1.2;
+}
+function spawnBinary() {
+  bodies = [
+    { pos: { x: -120, y: 0 }, vel: { x: 0, y: -1.1 }, mass: 8000, radius: 10, color: '#ffd27a' },
+    { pos: { x: 120, y: 0 }, vel: { x: 0, y: 1.1 }, mass: 8000, radius: 10, color: '#7ab8ff' },
+  ];
+  const rng = makeRng(99);
+  for (let i = 0; i < Number(nRange.value); i++) {
+    const r = 180 + rng() * 260;
+    const ang = rng() * Math.PI * 2;
+    const speed = Math.sqrt((G * 16000) / r) * (0.8 + rng() * 0.3);
+    bodies.push({
+      pos: { x: Math.cos(ang) * r, y: Math.sin(ang) * r },
+      vel: { x: -Math.sin(ang) * speed, y: Math.cos(ang) * speed },
+      mass: 1 + rng() * 2, radius: 1.6, color: `hsl(${(30 + rng() * 60).toFixed(0)},90%,72%)`,
+    });
+  }
+  camera.zoom = 1.0;
+}
+
+nRange.addEventListener('input', () => { nVal.textContent = nRange.value; });
+speedRange.addEventListener('input', () => { speedMul = Number(speedRange.value); speedVal.textContent = speedMul.toFixed(1) + '×'; });
+thetaRange.addEventListener('input', () => { theta = Number(thetaRange.value); thetaVal.textContent = theta.toFixed(2); });
+trailsBox.addEventListener('change', () => { trailsOn = trailsBox.checked; });
+document.getElementById('showTree').addEventListener('change', (e) => { showTree = e.target.checked; });
+document.getElementById('mergeOn').addEventListener('change', (e) => { mergeOn = e.target.checked; });
+document.getElementById('btnGalaxy').onclick = spawnGalaxy;
+document.getElementById('btnCluster').onclick = spawnCluster;
+document.getElementById('btnBinary').onclick = spawnBinary;
+document.getElementById('btnReset').onclick = spawnGalaxy;
+document.getElementById('btnPause').onclick = (e) => { paused = !paused; e.target.textContent = paused ? 'Resume' : 'Pause'; };
+
+canvas.addEventListener('wheel', (e) => {
+  e.preventDefault();
+  camera.zoom *= e.deltaY < 0 ? 1.08 : 0.93;
+  camera.zoom = Math.max(0.15, Math.min(6, camera.zoom));
+}, { passive: false });
+
+function screenToWorld(sx, sy) {
+  const cx = canvas.width / 2, cy = canvas.height / 2;
+  return { x: (sx - cx) / camera.zoom + camera.x, y: (sy - cy) / camera.zoom + camera.y };
+}
+
+let dragStart = null;
+canvas.addEventListener('mousedown', (e) => { dragStart = { sx: e.clientX, sy: e.clientY, t: performance.now() }; });
+canvas.addEventListener('mouseup', (e) => {
+  if (!dragStart) return;
+  const p0 = screenToWorld(dragStart.sx, dragStart.sy);
+  const p1 = screenToWorld(e.clientX, e.clientY);
+  bodies.push({
+    pos: p0,
+    vel: { x: (p0.x - p1.x) * 0.15, y: (p0.y - p1.y) * 0.15 },
+    mass: 400, radius: 7, color: '#ff8ac8',
+  });
+  dragStart = null;
+});
+
+spawnGalaxy();
+
+let last = performance.now();
+let frames = 0, fpsAccum = 0;
+
+function render() {
+  const now = performance.now();
+  const dt = Math.min(0.032, (now - last) / 1000);
+  last = now;
+
+  let lastTree = null;
+  if (!paused && bodies.length) {
+    const t0 = performance.now();
+    lastTree = buildTree(bodies);
+    const accs = bodies.map(() => ({ x: 0, y: 0 }));
+    for (let i = 0; i < bodies.length; i++) lastTree.accumulateForce(bodies[i], theta, accs[i]);
+    const dt = 0.6 * speedMul;
+    for (let i = 0; i < bodies.length; i++) {
+      bodies[i].vel.x += accs[i].x * dt; bodies[i].vel.y += accs[i].y * dt;
+      bodies[i].pos.x += bodies[i].vel.x * dt; bodies[i].pos.y += bodies[i].vel.y * dt;
+    }
+    if (mergeOn) bodies = resolveCollisions(bodies);
+    document.getElementById('stepTime').textContent = (performance.now() - t0).toFixed(2);
+  }
+
+  if (!trailsOn) {
+    ctx.fillStyle = '#05050a';
+    ctx.fillRect(0, 0, canvas.width, canvas.height);
+  } else {
+    ctx.fillStyle = 'rgba(5,5,10,0.18)';
+    ctx.fillRect(0, 0, canvas.width, canvas.height);
+  }
+
+  const cx = canvas.width / 2, cy = canvas.height / 2;
+  ctx.save();
+  ctx.translate(cx, cy);
+  ctx.scale(camera.zoom, camera.zoom);
+  ctx.translate(-camera.x, -camera.y);
+  if (showTree && lastTree) {
+    ctx.strokeStyle = 'rgba(120,170,255,0.35)';
+    ctx.lineWidth = 1 / camera.zoom;
+    for (const q of collectQuadBounds(lastTree)) {
+      ctx.strokeRect(q.x, q.y, q.size, q.size);
+    }
+  }
+  for (const b of bodies) {
+    ctx.beginPath();
+    ctx.fillStyle = b.color || '#fff';
+    const r = b.radius || Math.max(0.6, Math.cbrt(b.mass) * 0.4);
+    ctx.arc(b.pos.x, b.pos.y, r / camera.zoom > 0.4 ? r : 0.4, 0, Math.PI * 2);
+    ctx.fill();
+  }
+  ctx.restore();
+
+  frames++; fpsAccum += dt;
+  if (fpsAccum >= 0.5) {
+    document.getElementById('fps').textContent = Math.round(frames / fpsAccum);
+    document.getElementById('bcount').textContent = bodies.length;
+    frames = 0; fpsAccum = 0;
+  }
+
+  requestAnimationFrame(render);
+}
+requestAnimationFrame(render);
+</script>
+</body>
+</html>

